with dim_totals as (select s.region, s.city, count(*) as num_rows, max(e.quantity) as max_quantity, grouping_id() as level_id from inventory e inner join stores s on e.store_id = s.id group by grouping sets ((s.region, s.city), (s.region))) select region, city, level_id, case when region rlike '^(Central|North)$' then 'GROUP_B' else 'OTHER_ZONE' end as region_zone from dim_totals;
